// Üretilen dosya: tool/ozgun/uret.py. Fizik · Kinematik ve vektörler ayrıntılı (zor).
const ozPhysics6Zor = <(String, String, List<String>, String)>[
  ('İki vektör için |A + B| = |A − B| eşitliği sağlanıyorsa bu vektörler arasındaki açı kaçtır? (A ve B sıfır değil)', '90°', ['0°', '60°', '180°'], 'Her iki ifadenin karesi açıldığında 2A·B = −2A·B çıkar; A·B = 0 olur, yani vektörler diktir.'),
  ('Bir öğrenci kâğıda ortak başlangıç noktalı, uzunlukları 6 ve 8 birim olan ve aralarında 60° bulunan iki ok çiziyor. Oklardan birincisinden ikincisini çıkararak elde ettiği vektörün uzunluğu kaçtır?', '2√13 birim', ['2√37 birim', '2 birim', '10√2 birim'], '|A − B|² = 36 + 64 − 2·6·8·cos60° = 100 − 48 = 52; √52 = 2√13.'),
  ('Konum bağıntısı x(t) = 5 + 4t − t² (SI) olan bir hareketli ilk 3 saniyede toplam kaç metre yol alır?', '5 m', ['3 m', '4 m', '4,5 m'], 'v = 4 − 2t, t = 2 s\'de sıfır olur ve yön değişir. x(0) = 5, x(2) = 9, x(3) = 8; yol 4 + 1 = 5 m\'dir.'),
  ('Durgun hâlden x = 0 noktasından harekete başlayan bir cismin ivmesi a(t) = 2t (SI) ise t = 3 s\'deki konumu kaç metredir?', '9 m', ['18 m', '27 m', '6 m'], 'v(t) = t², x(t) = t³/3 olur. t = 3 s için x = 27/3 = 9 m.'),
  ('Bir bisikletli yolun ilk üçte birini 15 km/h, ikinci üçte birini 30 km/h, son üçte birini 90 km/h süratle alıyor. Tüm yoldaki ortalama sürati kaç km/h\'dir?', '27 km/h', ['45 km/h', '32 km/h', '22,5 km/h'], 'Her bölüm d ise toplam süre d/15 + d/30 + d/90 = d/9 olur; ortalama sürat 3d/(d/9) = 27 km/h.'),
  ('Bir sürücü belli bir yolu gidişte 30 km/h süratle alıyor. Dönüşte aynı yolu kullanarak tüm yolculuğun ortalama süratini 60 km/h yapmak istiyor. Dönüşte hangi süratle gitmelidir?', 'Hiçbir sonlu süratle ulaşamaz', ['90 km/h süratle dönmelidir', '120 km/h süratle dönmelidir', '60 km/h süratle dönmelidir'], 'Ortalama 60 km/h için toplam süre 2d/60 = d/30 olmalıdır; bu süre gidişte tamamen harcanmıştır, dönüşe hiç zaman kalmaz.'),
  ('Konumu x(t) = 2t² (SI) olan cismin 1 s ile 3 s arasındaki ortalama hızı, hangi anda anlık hızına eşittir?', 't = 2 s', ['t = 1,5 s', 't = 2,5 s', 't = 3 s'], 'Ortalama hız (18 − 2)/2 = 8 m/s\'dir. v = 4t = 8 için t = 2 s; sabit ivmede bu an aralığın tam ortasıdır.'),
  ('Bir kişi çalışmayan yürüyen merdiveni yürüyerek 60 s\'de çıkıyor; çalışan merdivende hiç yürümeden durursa 40 s\'de çıkıyor. Çalışan merdivende aynı hızla yürürse kaç saniyede çıkar?', '24 s', ['20 s', '50 s', '100 s'], 'Hızlar toplanır: 1/60 + 1/40 = 1/24 (merdiven boyu/s). Bu nedenle süre 24 s olur.'),
  ('Aralarında 1 km bulunan iki yürüyüşçü birbirine doğru 2\'şer km/h hızla yürüyor. Birinin yanındaki köpek, ikisi karşılaşana dek aralarında 10 km/h süratle durmadan gidip geliyor. Köpek toplam kaç km koşar?', '2,5 km', ['5 km', '1 km', '1,25 km'], 'Yürüyüşçüler 1/(2 + 2) = 0,25 saatte karşılaşır. Köpek bu süre boyunca 10 km/h ile koşar: 10·0,25 = 2,5 km.'),
  ('Bir motorbot akıntılı bir nehirde belli bir uzaklığa gidip geri dönüyor. Bu gidiş-dönüşün süresi, aynı uzaklığa durgun suda gidip dönme süresiyle karşılaştırıldığında nasıldır?', 'Akıntılı suda daha uzundur', ['İki süre birbirine eşittir', 'Akıntılı suda daha kısadır', 'Akıntının yönüne göre kısa ya da uzun olur'], 'Akıntıya karşı geçen fazladan süre, akıntı yönünde kazanılan süreden büyüktür; toplam süre d/(v−u) + d/(v+u) > 2d/v olur.'),
  ('100 m\'yi 10 s\'de koşan A ile 12,5 s\'de koşan B\'nin bitişe birlikte varması için A başlangıç çizgisinin kaç metre gerisinden başlamalıdır?', '25 m', ['20 m', '12,5 m', '22,5 m'], 'B 12,5 s\'de bitirir. A bu sürede 10·12,5 = 125 m koşar; bu yüzden 25 m geriden başlamalıdır.'),
  ('Bir nehirde motorbot ile ondan bir an düşürülen can simidi aynı noktadan ayrılıyor. Motorbot akıntı yönünde çeyrek saat gidip suya göre aynı hızla geri dönüyor. Dönüşe başladıktan kaç dakika sonra can simidine ulaşır?', '15 dakika', ['30 dakika', '7,5 dakika', 'Akıntı hızına bağlıdır'], 'Su çerçevesinde can simidi durgundur ve motorbot suya göre aynı süratle gidip döner; dönüş de gidiş kadar, yani 15 dakika sürer.'),
  ('20 m/s hızla giden bir otomobil 2 m/s² ivmeyle frenleniyor. Fren başladıktan 15 s sonra otomobil fren noktasından kaç metre uzaktadır?', '100 m', ['75 m', '125 m', '112,5 m'], 'Otomobil 20/2 = 10 s\'de durur ve frenli araç geri gitmez; durma mesafesi 20²/(2·2) = 100 m\'dir. 75 m, durmayı hesaba katmayan yanlış sonuçtur.'),
  ('Doğrusal bir yolda ilk hızı +20 m/s olan bir cismin ivmesi hareket boyunca sabit −2 m/s²\'dir. İlk 15 s\'de cismin aldığı toplam yol kaç metredir?', '125 m', ['75 m', '100 m', '137,5 m'], 'Cisim 10 s\'de 100 m gidip durur, sonra ters yönde 5 s\'de ½·2·25 = 25 m döner. Toplam yol 125 m, yer değiştirme 75 m\'dir.'),
  ('Durgun hâlden düzgün hızlanan bir cisim belli bir yolun sonunda 20 m/s hıza ulaşıyor. Bu yolun tam ortasından geçerken hızı yaklaşık kaç m/s\'dir?', '14,1 m/s', ['10 m/s', '15 m/s', '17,3 m/s'], 'v² yolla orantılıdır; yarı yolda v² yarıya iner: v = 20/√2 ≈ 14,1 m/s.'),
  ('Durgun hâlden düzgün hızlanan bir cisim belli bir yolun ilk yarısını t₁, ikinci yarısını t₂ sürede alıyor. t₁/t₂ oranı kaçtır?', '√2 + 1', ['1', '√2', '√2 − 1'], 'Tüm yol için T, yarısı için T/√2 gerekir. t₂ = T − T/√2 olduğundan t₁/t₂ = 1/(√2 − 1) = √2 + 1 ≈ 2,41.'),
  ('Sabit ivmeli bir cisim ilk 2 s\'de 10 m, sonraki 2 s\'de 26 m yol alıyorsa t = 0 anındaki hızı kaç m/s\'dir?', '1 m/s', ['5 m/s', '3 m/s', '0,5 m/s'], 'İvme (26 − 10)/2² = 4 m/s²\'dir. 10 = v₀·2 + ½·4·4 eşitliğinden v₀ = 1 m/s bulunur.'),
  ('Bir araç 400 m\'lik bir yolu durgun başlayıp durgun bitirecek. Hızlanma ve yavaşlama ivmelerinin büyüklüğü 2 m/s² ile sınırlıysa araç en çok yaklaşık kaç m/s hıza ulaşabilir?', '28,3 m/s', ['40 m/s', '20 m/s', '56,6 m/s'], 'Hızlanma ve yavaşlama yolları eşit, her biri 200 m\'dir: v² = 2·2·200 = 800, v ≈ 28,3 m/s.'),
  ('Aynı noktadan aynı anda çıkan, biri 10 m/s sabit hızla, diğeri durgun hâlden 2 m/s² ivmeyle giden iki araç arasındaki uzaklık yetişmeden önce en çok kaç metre olur?', '25 m', ['50 m', '100 m', '12,5 m'], 'Uzaklık hızlar eşitlenince (2t = 10, t = 5 s) en büyüktür: 10·5 − 5² = 25 m.'),
  ('Konum-zaman grafiğinin büküm noktasında (eğrinin bükülme yönünün değiştiği yerde) cisim için hangisi doğrudur?', 'İvmesi sıfırdır, hızı uç değer alır', ['Hızı sıfırdır', 'Cisim o anda geri dönmeye başlar', 'Konumu en büyük değerini alır'], 'Büküm noktasında ikinci türev, yani ivme sıfırdır; bu nedenle hız orada yerel bir en büyük ya da en küçük değerdedir.'),
  ('45 m yükseklikten bir top serbest bırakıldığı anda, tam altından yerden ikinci bir top 30 m/s hızla düşey yukarı atılıyor. Toplar kaç saniye sonra karşılaşır? (g = 10 m/s², hava direnci yok)', '1,5 s', ['3 s', '0,75 s', '2,25 s'], 'İki topun ivmesi aynı olduğundan bağıl hareket sabit hızlıdır: 45 m / 30 m/s = 1,5 s.'),
  ('25 m yüksekliğindeki bir kulenin tepesinden bir taş 20 m/s hızla düşey yukarı atılıyor. Taş kaç saniye sonra yere çarpar? (g = 10 m/s²)', '5 s', ['4 s', '1 s', '2,5 s'], '−25 = 20t − 5t² denklemi t² − 4t − 5 = 0 verir; pozitif kök t = 5 s\'dir.'),
  ('Bir kulenin tepesinden aynı anda biri 15 m/s ile yukarı, diğeri 15 m/s ile aşağı atılan iki taşın yere düşme anları arasında kaç saniye fark olur? (g = 10 m/s²)', '3 s', ['1,5 s', '6 s', 'Kule yüksekliğine bağlıdır'], 'Yukarı atılan taş, atıldığı seviyeye 2v/g = 3 s sonra aşağı yönlü 15 m/s ile döner; bundan sonrası öbür taşın hareketiyle aynıdır.'),
  ('v₀ hızıyla düşey yukarı atılan bir cisim çıkabileceği en büyük yüksekliğin yarısındayken hızı kaçtır? (Hava direnci yok)', 'v₀/√2', ['v₀/2', 'v₀/4', 'v₀(√2 − 1)'], 'v² = v₀² − 2g(h/2) ve h = v₀²/(2g) olduğundan v² = v₀²/2, yani v = v₀/√2.'),
  ('Belli bir yükseklikten serbest bırakılan bir cisim yere 4 s\'de düşüyor. Yüksekliğin ilk yarısını kaç saniyede düşer?', 'Yaklaşık 2,83 s', ['2 s', '1 s', 'Yaklaşık 3,46 s'], 'Düşülen yol zamanın karesiyle orantılıdır; yarı yol için t = 4/√2 = 2√2 ≈ 2,83 s.'),
  ('Bir musluktan su damlaları 0,2 s arayla serbestçe düşüyor. Ardışık iki damladan ikincisi koptuktan 0,4 s sonra iki damla arasındaki uzaklık kaç metredir? (g = 10 m/s²)', '1 m', ['0,2 m', '0,8 m', '1,8 m'], 'Önceki damla 0,6 s\'de 1,8 m, sonraki 0,4 s\'de 0,8 m düşmüştür; aradaki fark 1 m\'dir.'),
  ('Düşey yukarı atılan bir cismin tepe noktasına varmadan önceki son 1 saniyede aldığı yol için hangisi doğrudur? (g = 10 m/s², hava direnci yok)', 'Atış hızından bağımsız, 5 m\'dir', ['Atış hızıyla doğru orantılıdır', 'Her zaman 10 m\'dir', 'Atış hızının karesiyle orantılı olarak artar'], 'Hareket tersinden düşünülürse tepe noktasından serbest düşmenin ilk saniyesidir: ½·10·1² = 5 m (atış en az 1 s sürüyorsa).'),
  ('Her basamağın yüksekliği ve genişliği 0,2 m olan bir merdivenin en üst basamağının kenarından 2,5 m/s hızla yatay yuvarlanan top ilk olarak kaçıncı basamağa çarpar? (g = 10 m/s²)', '7. basamağa', ['5. basamağa', '6. basamağa', '8. basamağa'], 'Basamak köşelerinden geçen eğik çizgi y = x\'tir; 5t² = 2,5t eşitliğinden t = 0,5 s ve x = 1,25 m bulunur. 1,25/0,2 = 6,25 olduğundan top 7. basamağın üstüne düşer.'),
  ('Yatay atılan bir cismin herhangi bir andaki hız vektörünün yatayla yaptığı açı α, aynı andaki yer değiştirme vektörünün yatayla yaptığı açı β ise hangisi doğrudur?', 'tanα = 2·tanβ', ['tanα = tanβ', 'tanβ = 2·tanα', 'α = 2β'], 'tanα = gt/v₀, tanβ = (½gt²)/(v₀t) = gt/(2v₀) olduğundan tanα = 2tanβ.'),
  ('Mars\'ta yerçekimi ivmesi yaklaşık 3,7 m/s²\'dir. Aynı yükseklikten yatay atılan bir taşın Mars\'taki yatay menzili Dünya\'dakine göre nasıldır? (g_Dünya ≈ 9,8 m/s², atmosfer ihmal)', 'Yaklaşık 1,6 kat büyüktür', ['Yaklaşık 2,6 kat büyüktür', 'Yaklaşık 1,6 kat küçüktür', 'Eşittir'], 'Menzil uçuş süresiyle, uçuş süresi 1/√g ile orantılıdır: √(9,8/3,7) ≈ 1,63.'),
  ('Eğik atılan bir cismin en büyük yüksekliğinin yatay menzile eşit olması için atış açısı θ hangi koşulu sağlamalıdır?', 'tanθ = 4', ['tanθ = 1', 'tanθ = 2', 'sinθ = 1/4'], 'H/R = tanθ/4 bağıntısından H = R için tanθ = 4, yani θ ≈ 76° bulunur.'),
  ('Aynı ilk hızla 30° ve 60° açılarla atılan iki cismin uçuş sürelerinin oranı (30°\'lik / 60°\'lik) kaçtır?', '√3/3', ['1', '√3', '1/2'], 'Uçuş süresi 2v₀sinθ/g\'dir; oran sin30°/sin60° = (1/2)/(√3/2) = 1/√3.'),
  ('Yatayla 53° açıyla 50 m/s hızla atılan bir cismin 7. saniye sonundaki hızının büyüklüğü yaklaşık kaç m/s\'dir? (sin53° = 0,8, cos53° = 0,6, g = 10 m/s²)', '42,4 m/s', ['30 m/s', '50 m/s', '58,31 m/s'], 'Yatay bileşen 30 m/s, düşey bileşen 40 − 70 = −30 m/s olur; büyüklük 30√2 ≈ 42,4 m/s.'),
  ('Yatayla 60° açıyla 20 m/s hızla atılan bir cismin hız vektörü ilk hız vektörüne kaç saniye sonra dik olur? (g = 10 m/s²)', 'Yaklaşık 2,31 s', ['Yaklaşık 1,73 s', '2 s', 'Yaklaşık 3,46 s'], 'Dikliği v₀·v = 0 koşulu belirler: v₀² − v₀·g·t·sinθ = 0, t = v₀/(g·sinθ) = 20/(10·0,866) ≈ 2,31 s. Bu süre uçuş süresinden (3,46 s) kısadır.'),
  ('8 m yüksekliğindeki bir duvarın tepesinden bir top yatayla yukarı doğru 37° açı yapacak biçimde 10 m/s hızla atılıyor. Top duvarın dibinden yatayda kaç metre uzağa düşer? (sin37° = 0,6, cos37° = 0,8, g = 10 m/s²)', '16 m', ['9,6 m', '12 m', '20,5 m'], 'Bileşenler 8 m/s yatay, 6 m/s düşeydir. −8 = 6t − 5t² denkleminden t = 2 s; yatay uzaklık 8·2 = 16 m.'),
  ('11 m yükseklikteki bir balkondan bir taş yatayın 37° altına doğru 10 m/s hızla fırlatılıyor. Taş balkonun dibinden yatayda kaç metre uzağa düşer? (sin37° = 0,6, cos37° = 0,8, g = 10 m/s²)', '8 m', ['6 m', '11 m', '10,5 m'], 'Düşey ilk hız aşağı 6 m/s\'dir: 11 = 6t + 5t², t = 1 s. Yatay hız 8 m/s olduğundan uzaklık 8 m\'dir.'),
  ('20 m/s hızla atılan bir topun aynı seviyedeki 20 m uzaktaki hedefe düşmesi için atış açısı hangisi olabilir? (g = 10 m/s², hava direnci yok)', '15° ya da 75°', ['30° ya da 60°', 'Yalnız 45°', '22,5° ya da 67,5°'], 'R = v₀²sin2θ/g eşitliği 20 = 40·sin2θ verir; sin2θ = 0,5, 2θ = 30° ya da 150°.'),
  ('15 m yükseklikteki bir pencereden 10 m/s hızla atılan bir top hangi doğrultuda atılırsa atılsın yere hangi süratle çarpar? (g = 10 m/s², hava direnci yok)', '20 m/s', ['10√2 m/s', '25 m/s', 'Atış yönüne bağlı olarak değişir'], 'Yatay bileşen sabit kalır, düşey bileşenin karesi 2gh kadar artar; v² = v₀² + 2gh = 100 + 300 = 400, v = 20 m/s.'),
  ('Yüksek bir uçurumun kenarından eğik atılan bir taşın yatay menzilini en büyük yapan atış açısı için hangisi doğrudur?', '45°\'den küçüktür', ['Tam olarak 45°\'dir', '45°\'den büyüktür', '90°\'dir'], 'Taş atış seviyesinin altına indiği için uçuş süresi uzar; bu ek süreden yararlanmak için daha alçak açılar avantajlıdır.'),
  ('A gemisi başlangıç noktasında doğuya 4 m/s ile, B gemisi A\'nın 100 m kuzeyinde güneye 3 m/s ile hareket etmeye başlıyor. İki gemi arasındaki uzaklık en az kaç metreye iner?', '80 m', ['60 m', '100 m', '0 m'], 'B\'nin A\'ya göre hızı (−4, −3) m/s, A\'ya göre konumu (0, 100) m\'dir. En küçük uzaklık |r × v|/|v| = 400/5 = 80 m.'),
  ('60 m genişliğindeki nehirde akıntı hızı 5 m/s, kayığın suya göre hızı 3 m/s\'dir. Kayık karşı kıyıya en az sürüklenecek biçimde yönlendirilirse akıntı yönünde en az kaç metre sürüklenir?', '80 m', ['100 m', '45 m', '36 m'], 'Kayık akıntıdan yavaş olduğundan tam karşıya çıkamaz. En az sürüklenme d·√(u² − v²)/v = 60·4/3 = 80 m\'dir.'),
  ('Havaya göre 100 km/h hızla uçan uçak, doğuya doğru esen 50 km/h\'lik rüzgârı dengeleyerek tam kuzeye gidiyor. Yere göre hızı yaklaşık kaç km/h\'dir?', '86,6 km/h', ['150 km/h', '111,8 km/h', '50 km/h'], 'Yere göre hız √(100² − 50²) = 50√3 ≈ 86,6 km/h olur.'),
  ('Düz bir yolda kaymadan yuvarlanan bisiklet tekerleğinin çevresine yapıştırılmış bir reflektör, yoldaki bir gözlemciye göre nasıl bir yörünge çizer?', 'Sikloid', ['Çember', 'Doğru parçası', 'Parabol'], 'Tekerleğe göre çember çizen nokta, tekerlekle birlikte ilerlediği için yere göre sikloid adlı kemerli eğriyi çizer.'),
  ('Serbest düşme süresinin t = k·hᵃ·gᵇ biçiminde yükseklik h ve yerçekimi ivmesi g\'ye bağlı olduğu varsayılıyor (k birimsiz). Boyut analizine göre a ve b kaçtır?', 'a = 1/2, b = −1/2', ['a = 1, b = −1', 'a = 2, b = 1', 'a = −1/2, b = 1/2'], 'T = Lᵃ·(L·T⁻²)ᵇ eşitliğinden a + b = 0 ve −2b = 1; buradan b = −1/2, a = 1/2 bulunur.'),
  ('Durgun hâlden düzgün hızlanan bir cismin konumu, zamanın karesine karşı çizildiğinde eğimi 3 m/s² olan bir doğru elde ediliyor. Cismin ivmesi kaç m/s²\'dir?', '6 m/s²', ['3 m/s²', '1,5 m/s²', '9 m/s²'], 'x = ½·a·t² bağıntısında x\'in t²\'ye karşı eğimi a/2\'dir; a = 2·3 = 6 m/s².'),
  ('14. yüzyılda Oxford\'daki Merton Koleji düşünürlerine atfedilen \'ortalama hız teoremi\' neyi ifade eder?', 'Düzgün ivmeli yolun, ortalama hızla sabit gidilen yola eşitliğini', ['Hızın, düşen cismin ağırlığıyla orantılı olduğunu', 'Hareket eden her cismin sonunda duracağını', 'Yerçekimi ivmesinin her yerde aynı olduğunu'], 'Teorem, düzgün hızlanan cismin aldığı yolun, ilk ve son hızların ortalamasıyla sabit hızla aynı sürede alınacak yola eşit olduğunu söyler.'),
  ('Galileo, eğik düzlem deneylerinde zaman aralıklarını ölçmek için hangi yöntemi kullandığını anlatmıştır?', 'Akan suyu tartmayı', ['Sarkaçlı duvar saatini', 'Kum saatini', 'Atom saatini'], 'Galileo, büyük bir kaptan ince bir borudan akan suyu toplayıp tartarak süreleri karşılaştırdığını yazmıştır; sarkaçlı saat ondan sonra Huygens tarafından yapılmıştır.'),
  ('Doğuya 20 m/s ile giden bir araç 5 s süren bir dönüşle aynı süratte kuzeye yöneliyor. Bu dönüş boyunca ortalama ivmesinin büyüklüğü yaklaşık kaç m/s²\'dir?', '5,7 m/s²', ['0 m/s²', '4 m/s²', '11,3 m/s²'], '|Δv| = 20√2 ≈ 28,3 m/s; ortalama ivme 28,3/5 ≈ 5,7 m/s². Sürat değişmese de hız vektörü değiştiği için ivme vardır.'),
  ('Büyüklükleri 2, 3 ve 10 birim olan üç vektörün bileşkesinin alabileceği en küçük değer kaç birimdir?', '5', ['0', '15', '1'], 'En büyük vektöre diğer ikisi tam ters yönde eklenirse bileşke 10 − (2 + 3) = 5 olur; sıfır olamaz çünkü 10 > 2 + 3.'),
  ('Büyüklükleri eşit olan A ve B vektörleri için A + B ile A − B vektörleri arasındaki açı kaç derecedir?', '90°', ['0°', '45°', 'Vektörler arasındaki açıya bağlıdır'], '(A + B)·(A − B) = |A|² − |B|² = 0 olduğundan iki vektör daima diktir; eşkenar dörtgenin köşegenleri de diktir.'),
  ('Yere çarptıkça esnek olarak sekip hep aynı yüksekliğe çıkan bir topun hız-zaman grafiği (yukarı yön pozitif) nasıl görünür?', 'Eğimi −g olan, çarpmalarda −v\'den +v\'ye sıçrayan parçalar', ['Zaman eksenine paralel yatay doğrular', 'Hep pozitif değerli, yukarı açılan paraboller', 'Orijinden geçen tek bir eğik doğru'], 'Havadayken ivme hep −g olduğundan grafik eğimi −g olan doğru parçalarıdır; her çarpmada hız aniden ters işaret alır.'),
  ('Bir aracın ivme-zaman grafiği 0–5 s arasında +2 m/s², 5–10 s arasında −2 m/s² değerinde iki yatay parçadan oluşuyor. Araç t = 0\'da durgunsa 10. saniyedeki hızı ve o ana kadar yaptığı yer değiştirme nedir?', '0 m/s ve 50 m', ['0 m/s ve 0 m', '10 m/s ve 50 m', '0 m/s ve 25 m'], '5 s\'de hız 10 m/s olur, sonra 5 s\'de sıfıra iner. Hız hiç negatif olmadığından yer değiştirme 25 + 25 = 50 m\'dir.'),
  ('Sabit v hızıyla giden bir aracı, yanından geçtiği anda durgun hâlden sabit ivmeyle harekete geçen bir polis aracı kovalıyor. Polis aracı yetiştiği anda hangi hıza ulaşmıştır?', '2v', ['v', '1,5v', 'v√2'], 'Aynı sürede eşit yol alınır; polis aracının ortalama hızı v olmalıdır. Durgun başlayan düzgün hızlanmada ortalama hız son hızın yarısı olduğundan son hız 2v\'dir.'),
  ('30 m/s ile giden A aracı, önünde aynı yönde 20 m/s ile giden B aracına 25 m kalınca fren yapmaya başlıyor. B hızını korursa A\'nın çarpmaması için frenleme ivmesi en az kaç m/s² olmalıdır?', '2 m/s²', ['18 m/s²', '4 m/s²', '8 m/s²'], 'B\'ye göre düşünülürse A 10 m/s bağıl hızla yaklaşır ve bu bağıl hızı 25 m içinde sıfırlamalıdır: a = 10²/(2·25) = 2 m/s².'),
  ('A aracı durgun hâlden 2 m/s² ivmeyle harekete geçiyor. Aynı noktadan 2 s sonra B aracı durgun hâlden 4,5 m/s² ivmeyle aynı yöne çıkıyor. B, A\'ya A\'nın hareketinin kaçıncı saniyesinde yetişir?', '6. saniyede', ['4. saniyede', '3. saniyede', '4,5. saniyede'], 't² = 2,25(t − 2)² eşitliğinden t = 1,5(t − 2), yani t = 6 s bulunur.'),
  ('Bir model roket yerden düşey olarak 20 m/s² sabit ivmeyle 5 s yükseliyor, sonra yakıtı bitiyor. Roket yerden en çok kaç metre yükseğe çıkar? (g = 10 m/s², hava direnci yok)', '750 m', ['250 m', '500 m', '1000 m'], '5 s sonunda hız 100 m/s, yükseklik 250 m\'dir. Sonra serbestçe 100²/20 = 500 m daha yükselir; toplam 750 m.'),
  ('Büyüklüğü 10 birim olan A vektörü +x ekseniyle 37°, büyüklüğü 10 birim olan B vektörü +x ekseniyle 53° açı yapıyor (ikisi de birinci bölgede). A + B\'nin büyüklüğü kaç birimdir? (sin37° = 0,6, cos37° = 0,8)', '14√2', ['20', '2√2', '10√3'], 'A = (8, 6), B = (6, 8) olduğundan A + B = (14, 14); büyüklüğü 14√2 ≈ 19,8 birimdir.'),
  ('|A| = 2|B| olan iki vektörün toplamı A + B, B vektörüne diktir. A ile B arasındaki açı kaç derecedir?', '120°', ['90°', '60°', '112,5°'], '(A + B)·B = 0 ise A·B = −|B|²; 2|B|²cosθ = −|B|² verir, cosθ = −1/2, θ = 120°.'),
  ('Uluslararası anlaşmayla benimsenmiş standart yerçekimi ivmesi (g₀) değeri hangisidir?', '9,80665 m/s²', ['9,81000 m/s²', '9,78033 m/s²', '10,00000 m/s²'], 'Standart yerçekimi ivmesi 1901\'de 9,80665 m/s² olarak tanımlanmıştır; hesaplarda kullanılan 9,8 ve 10 bunun yuvarlanmış biçimleridir.'),
  ('Düşey yukarı atılan bir cismin hızı ilk hızının yarısına indiğinde, cisim çıkabileceği en büyük yüksekliğin ne kadarına ulaşmıştır?', '3/4\'üne', ['1/2\'sine', '1/4\'üne', '2/3\'üne'], 'v² = v₀² − 2gh ile v = v₀/2 için h = 3v₀²/(8g) bulunur; bu, en büyük yükseklik olan v₀²/(2g)\'nin 3/4\'üdür.'),
  ('H yükseklikten bir top serbest bırakıldığı anda tam altındaki yerden ikinci bir top v₀ hızıyla düşey yukarı atılıyor. Toplar tam H/2 yüksekliğinde karşılaşıyorsa v₀ nedir?', '√(gH)', ['√(2gH)', '√(gH/2)', '2√(gH)'], 'Karşılaşma süresi H/v₀\'dır. Düşen top bu sürede H/2 yol almalıdır: ½g(H/v₀)² = H/2, buradan v₀² = gH.'),
  ('Hızı v(t) = 6 − 2t (SI) olan bir cismin ilk 5 saniyede aldığı toplam yol kaç metredir?', '13 m', ['5 m', '9 m', '4,5 m'], 'Cisim t = 3 s\'de durur. 0–3 s arasında 9 m ileri, 3–5 s arasında 4 m geri gider; yol 13 m, yer değiştirme 5 m\'dir.'),
  ('Bir cismin hızı konuma bağlı olarak v(x) = 2x (SI) bağıntısıyla değişiyor. Cisim x = 3 m\'deyken ivmesi kaç m/s²\'dir?', '12 m/s²', ['6 m/s²', '2 m/s²', '4,5 m/s²'], 'a = dv/dt = v·(dv/dx) = (2·3)·2 = 12 m/s².'),
  ('Konumu x(t) = t³ − 3t² (SI) olan bir cisim 0 < t < 1 s aralığında nasıl hareket eder?', '−x yönünde hızlanarak', ['−x yönünde yavaşlayarak', '+x yönünde hızlanarak', '+x yönünde yavaşlayarak'], 'v = 3t² − 6t ve a = 6t − 6 bu aralıkta ikisi de negatiftir; hız ile ivme aynı yönlü olduğundan cisim −x yönünde hızlanır.'),
  ('Durgun hâlden başlayan bir cismin ivmesi a(t) = 6 − 2t (SI) bağıntısıyla azalıyor. Cismin ulaşacağı en büyük hız kaç m/s\'dir?', '9 m/s', ['6 m/s', '18 m/s', '3 m/s'], 'v(t) = 6t − t² olur; ivme t = 3 s\'de sıfırlanır ve hız en büyük değerine ulaşır: 18 − 9 = 9 m/s.'),
  ('Bir cismin ivmesi a = −k·v biçiminde hızıyla orantılı ve hıza zıt yönlüyse (k sabit, pozitif) hızı zamanla nasıl değişir?', 'Üstel olarak azalır', ['Doğrusal olarak azalıp sıfır olur', 'Sabit kalır', 'Önce azalır sonra artar'], 'dv/dt = −k·v denkleminin çözümü v = v₀·e^(−kt)\'dir; hız her eşit sürede aynı oranda azalır.'),
  ('Yatayla 53° açıyla 20 m/s hızla atılan bir cismin hız vektörü kaçıncı saniyede yatayın 45° altına yönelir? (sin53° = 0,8, cos53° = 0,6, g = 10 m/s²)', '2,8 s', ['1,6 s', '3,2 s', '0,45 s'], 'Yatay bileşen 12 m/s\'dir. Düşey bileşen −12 m/s olmalıdır: 16 − 10t = −12, t = 2,8 s.'),
  ('Eğik atışta hızın yatay bileşeni değişmeden düşey bileşeni iki katına çıkarılırsa en büyük yükseklik ve menzil nasıl değişir?', 'Yükseklik 4 katına, menzil 2 katına çıkar', ['İkisi de 4 katına çıkar', 'İkisi de 2 katına çıkar', 'Yükseklik 2 katına, menzil 4 katına çıkar'], 'Yükseklik v_y² ile orantılıdır; menzil v_x·(2v_y/g) olduğundan v_y ile doğru orantılıdır.'),
  ('Akıntılı bir nehirde suya göre aynı hızla yüzen iki yüzücüden biri akıntı boyunca belli bir şamandıraya gidip dönüyor, diğeri aynı uzaklıktaki karşı kıyıya dik gidip dönüyor. Hangisi daha önce başlangıca döner?', 'Karşı kıyıya gidip dönen', ['Akıntı boyunca gidip dönen', 'İkisi aynı anda döner', 'Akıntının hızına göre ikisi de olabilir'], 'Akıntı boyunca süre 2Lv/(v² − u²), dik geçişte 2L/√(v² − u²)\'dir; ikincisi her zaman daha kısadır.'),
  ('Düzgün hızlanan bir araç A noktasından 4 m/s, 20 m ötedeki B noktasından 6 m/s hızla geçiyor. AB yolunun tam ortasından geçerken hızı yaklaşık kaç m/s\'dir?', '5,1 m/s', ['5 m/s', '4,9 m/s', '5,25 m/s'], 'Yol ortasında v² = (v_A² + v_B²)/2 = (16 + 36)/2 = 26 olur; v ≈ 5,1 m/s.'),
  ('Düzgün hızlanan bir cisim için yolun tam ortasındaki hız ile sürenin tam ortasındaki hız karşılaştırılırsa hangisi doğrudur?', 'Yol ortasındaki hız daha büyüktür', ['Süre ortasındaki hız daha büyüktür', 'İkisi her zaman eşittir', 'Yavaşlayan harekette süre ortasındaki daha büyüktür'], 'Süre ortasında hız (v₁ + v₂)/2, yol ortasında √((v₁² + v₂²)/2)\'dir; kareli ortalama aritmetik ortalamadan büyüktür.'),
  ('Düzgün yavaşlayan bir araç ilk 2 s\'de 30 m, sonraki 2 s\'de 18 m yol alıyor. Araç tam durana kadar bu 4 s\'den sonra kaç metre daha gider?', '6 m', ['8 m', '12 m', '10,5 m'], 'Yol farkı −12 m = a·2² olduğundan a = −3 m/s²; 30 = 2v₀ − 6 eşitliğinden v₀ = 18 m/s. 4 s sonunda v = 6 m/s, kalan yol v²/(2·3) = 6 m.'),
  ('Aynı noktadan 1 s arayla, ikisi de 20 m/s hızla düşey yukarı atılan iki top, ilk top atıldıktan kaç saniye sonra yan yana gelir? (g = 10 m/s²)', '2,5 s', ['2 s', '1,5 s', '3,25 s'], '20t − 5t² = 20(t − 1) − 5(t − 1)² eşitliği 10t = 25 verir; t = 2,5 s. Bu anda ilk top inmekte, ikincisi çıkmaktadır.'),
  ('Düz zeminden eğik atılıp yine zemine düşen bir cismin tüm uçuş boyunca ortalama hızı neye eşittir? (Hava direnci yok)', 'İlk hızın yatay bileşenine', ['İlk hızın büyüklüğüne', 'Sıfıra', 'İlk hızın düşey bileşenine'], 'Yer değiştirme yalnız yatay menzildir; menzil/uçuş süresi tam olarak sabit yatay hız bileşenini verir.'),
  ('Bir cirit atıcısı ciriti aynı hızla 45° yerine 40° ile atıyor. Hava direnci ihmal edilirse menzil nasıl değişir?', 'Çok az azalır', ['Yarıya iner', 'Artar', 'Hiç değişmez, aynı kalır'], 'Menzil sin2θ ile orantılıdır: sin80° ≈ 0,985; menzil yalnız yaklaşık %1,5 azalır. En büyük değer 45°\'nin çevresinde çok yayvan bir tepedir.'),
  ('Jeodezide ve depremlerde yer ivmesini belirtmek için kullanılan, adını Galileo\'dan alan \'Gal\' birimi neye eşittir?', '1 cm/s²', ['1 m/s²', '1 km/s²', '9,8 m/s²'], '1 Gal = 1 cm/s² = 0,01 m/s²\'dir; yerçekimi ivmesi yaklaşık 980 Gal\'dir.'),
  ('6 m/s ile koşan bir yolcu, 20 m önündeki durgun otobüs onu fark etmeden 1 m/s² ivmeyle kalkınca otobüsü yakalamaya çalışıyor. Sonuç ne olur?', 'Yetişemez; aralarında en az 2 m kalır', ['6 s sonra yetişir', 'Yetişemez; aralarında en az 20 m kalır', '2 s sonra yetişir'], '6t = 20 + 0,5t² denkleminin gerçek kökü yoktur. Hızlar t = 6 s\'de eşitlenir; o anda aradaki uzaklık 20 + 18 − 36 = 2 m\'dir.'),
  ('14. yüzyılda hızı zamana karşı bir çizgiyle gösterip altında kalan alanın alınan yolu verdiğini geometrik olarak açıklayan Fransız düşünür kimdir?', 'Nicole Oresme', ['Jean Buridan', 'René Descartes', 'Thomas Bradwardine'], 'Oresme\'nin \'enlemler\' adını verdiği bu çizimler, bugünkü hız-zaman grafiğinin öncüsü sayılır.'),
  ('x ekseni üzerindeki bir cismin bir andaki konumu x > 0, hızı v < 0 ve ivmesi a > 0\'dır. Bu anda cisim için hangisi doğrudur?', 'Başlangıca doğru giderken yavaşlıyor', ['Başlangıçtan uzaklaşırken hızlanıyor', 'Başlangıca doğru giderken hızlanıyor', 'Başlangıçtan uzaklaşırken yavaşlıyor'], 'Pozitif tarafta olup negatif yönde gittiğinden başlangıca yaklaşıyor; hız ile ivme zıt işaretli olduğundan yavaşlıyor.'),
  ('Bir öğrenci 100,0 m\'lik yolu 10,0 s\'de koşuyor. Yol ölçümünün belirsizliği ±0,1 m, süre ölçümününki ±0,1 s ise hesaplanan ortalama süratin belirsizliği yaklaşık ne kadardır?', '±0,1 m/s', ['±0,01 m/s', '±1 m/s', '±0,2 m/s'], 'Bağıl belirsizlikler toplanır: 0,1/100 + 0,1/10 ≈ %1,1; 10 m/s\'nin %1,1\'i ≈ 0,11 m/s.'),
  ('Bir öğrenci konum-zaman verisinden hızı, ardışık iki ölçümün farkını süre farkına bölerek buluyor. Ölçümler arası süreyi çok küçültmek hangi sakıncayı doğurabilir?', 'Konum hatalarının hızdaki etkisini büyütür', ['Hızın birimini değiştirir', 'Sonucu her zaman sıfır yapar', 'Ortalama hızı anlık hızdan büyütür'], 'Δx küçüldükçe konum ölçümündeki sabit belirsizlik Δx\'e göre büyür; bu da hesaplanan hızı gürültülü hâle getirir.'),
  ('Buz üzerinde kayan bir hokey diskinin hızı 8 m yol boyunca düzgün olarak 10 m/s\'den 6 m/s\'ye iniyor. Aynı ivmeyle disk durana kadar kaç metre daha kayar?', '4,5 m', ['6 m', '3 m', '12,5 m'], 'a = (36 − 100)/(2·8) = −4 m/s²; kalan yol 6²/(2·4) = 4,5 m.'),
  ('Aralarında 100 m bulunan iki araç aynı anda durgun hâlden birbirine doğru 2 m/s² ve 3 m/s² ivmelerle harekete geçiyor. Yaklaşık kaç saniye sonra karşılaşırlar?', '6,3 s', ['4 s', '10 s', '4,47 s'], 'Aldıkları yolların toplamı 100 m olmalıdır: ½(2 + 3)t² = 100, t = √40 ≈ 6,3 s.'),
  ('Konum-zaman grafiği t = 3 s\'de tepe noktası x = 9 m olan bir parabol olan cisim t = 0\'da x = 0\'dadır. Cismin ilk hızı ve ivmesi nedir?', '6 m/s ve −2 m/s²', ['3 m/s ve −1 m/s²', '9 m/s ve −3 m/s²', '6 m/s ve −1 m/s²'], 'x = v₀t + ½at²; tepe noktasında v₀ + 3a = 0 ve 3v₀ + 4,5a = 9. Çözüm v₀ = 6 m/s, a = −2 m/s².'),
  ('Eğik atışta yatay menzil R ve en büyük yükseklik H biliniyorsa atış açısı θ hangi bağıntıyla bulunur?', 'tanθ = 4H/R', ['tanθ = H/R', 'tanθ = 2H/R', 'sinθ = H/(2R)'], 'H = v₀²sin²θ/(2g) ve R = 2v₀²sinθcosθ/g bölündüğünde H/R = tanθ/4 çıkar.'),
  ('İki vektör için |A + B| = 10 ve |A − B| = 6 olduğu biliniyor. A·B skaler çarpımı kaçtır?', '16', ['64', '4', '32'], '|A + B|² − |A − B|² = 4A·B eşitliğinden 100 − 36 = 64, A·B = 16.'),
  ('Bir karınca kenarı 2 m olan bir küpün yüzeyinde yürüyerek bir köşeden en uzak köşeye gidiyor. Alabileceği en kısa yol yer değiştirmesinden ne kadar uzundur?', 'Yaklaşık 1 m', ['Hiç uzun değildir', 'Yaklaşık 2,5 m', 'Yaklaşık 0,1 m'], 'Yüzey açınımında en kısa yol √(2² + 4²) = 2√5 ≈ 4,47 m, yer değiştirme 2√3 ≈ 3,46 m\'dir; fark yaklaşık 1 m.'),
  ('|A| = 3 ve |B| = 4 olan iki vektör için |A + B|² + |A − B|² ifadesinin değeri kaçtır?', '50', ['25', '49', 'Açıya bağlıdır'], 'Paralelkenar kuralına göre bu toplam 2(|A|² + |B|²) = 2(9 + 16) = 50\'dir ve açıdan bağımsızdır.'),
  ('Bir yolculuk iki farklı sabit süratle yapılacak. \'Eşit sürelerde\' ve \'eşit yollarda\' bu iki süratle gidilmesi karşılaştırılırsa hangisi daha büyük ortalama sürat verir? (Süratler farklı)', 'Eşit sürelerde gitmek', ['Eşit yollarda gitmek', 'İkisi her zaman aynı sonucu verir', 'Hangi süratin önce kullanıldığına bağlıdır'], 'Eşit sürede ortalama aritmetik, eşit yolda harmonik ortalamadır; farklı sayılarda aritmetik ortalama her zaman daha büyüktür.'),
  ('Biri sabit hızlı, diğeri sabit ivmeli iki cismin konum-zaman eğrileri en fazla kaç kez kesişebilir?', '2 kez', ['1 kez', '3 kez', 'Sonsuz kez'], 'Doğru ile parabolün kesişimi ikinci dereceden bir denklemdir; en çok iki kökü olduğundan iki cisim en çok iki kez yan yana gelir.'),
  ('Yerden 20 m/s ile düşey yukarı fırlatılan bir bilye ile aynı anda, tam üstündeki 40 m yükseklikten bir taş serbest bırakılıyor. İkisi yerden kaç metre yükseklikte buluşur? (g = 10 m/s²)', '20 m', ['15 m', '25 m', '10 m'], 'Buluşma süresi 40/20 = 2 s\'dir. Taş bu sürede 20 m düşer ve 20 m yükseklikte bilyeyle buluşur; bilye o anda tam tepe noktasındadır.'),
  ('Galileo, ağır cisimlerin daha hızlı düştüğü görüşünü bir düşünce deneyiyle çürütmüştür. Bu deneyde hangi durum incelenir?', 'Ağır ve hafif iki taşın birbirine bağlanması', ['İki taşın farklı sıvılarda düşürülmesi', 'Taşların eğik düzlemde yuvarlanması', 'Bir taşın iple sarkaç gibi sallanması'], 'Bağlı sistem hem hafif taşın frenlemesiyle daha yavaş hem de toplam ağırlığı büyük olduğu için daha hızlı düşmeliydi; bu çelişki görüşü çürütür.'),
  ('Serbest düşmede düşülen yol ile ulaşılan hız arasındaki ilişkiyi gösteren v = √(2gh) bağıntısına göre hız-yol grafiği nasıldır?', 'Orijinden geçen, giderek yataylaşan bir eğri', ['Orijinden geçen bir doğru', 'Yukarı doğru açılan bir parabol', 'Yatay bir doğru'], 'Hız yolun kareköküyle orantılıdır; böyle bir eğri başta dik yükselir, sonra eğimi azalır.'),
  ('Konumları x_A = t² ve x_B = 4t − 4 (SI) olan iki cisim için hangisi doğrudur?', 'Yalnız t = 2 s\'de, eşit hızlarla yan yana gelirler', ['Hiç karşılaşmazlar', 'İki farklı anda karşılaşırlar', 't = 4 s\'de karşılaşırlar'], 't² − 4t + 4 = (t − 2)² = 0 tek kök verir. O anda hızlar 2t = 4 ve 4 m/s ile eşittir; eğriler birbirine teğettir.'),
  ('Bir kayakla atlayıcı rampayı 25 m/s ile yatay olarak terk edip yatayla 37° eğimli bir yamaca iniyor. Havada kaç saniye kalır? (tan37° = 0,75, g = 10 m/s²)', '3,75 s', ['2,5 s', '1,9 s', '5 s'], 'Yamaç üzerinde y/x = tan37° olmalıdır: (5t²)/(25t) = 0,75 eşitliğinden t = 3,75 s.'),
  ('Bir vektörün bileşenleri (a, b) iken eksenler 90° döndürülerek yeni x′ ekseni eski y ekseni yönüne getiriliyor. Aynı vektörün yeni bileşenleri ne olur?', '(b, −a)', ['(a, b)', '(−b, a)', '(b, a)'], 'Yeni x′ birim vektörü eski j\'dir, yeni y′ birim vektörü eski −i\'dir. x′ bileşeni b, y′ bileşeni −a olur; büyüklük değişmez.'),
  ('Fransızca \'cinématique\' (kinematik) terimini 1834\'te bilimlerin sınıflandırılması üzerine yazdığı eserde ortaya atan bilim insanı kimdir?', 'André-Marie Ampère', ['Pierre-Simon Laplace', 'Joseph-Louis Lagrange', 'Augustin Cauchy'], 'Ampère, hareketi nedenlerinden bağımsız olarak inceleyen bilim dalına Yunanca \'kinema\' (hareket) sözcüğünden türettiği bu adı vermiştir.'),
  ('Çok kısa süreli flaşlarla mermi ve süt damlası gibi çok hızlı olayları donduran stroboskopik fotoğrafçılığı geliştiren MIT\'li mühendis kimdir?', 'Harold Edgerton', ['Edwin Hubble', 'Ernst Mach', 'Eadweard Muybridge'], 'Edgerton\'ın elektronik flaş tekniği, hızlı hareketlerin kinematik çözümlemesinde yaygın biçimde kullanılmıştır.'),
  ('Aynı süratle (v) giden iki aracın hız vektörleri arasında 60° açı vardır. Araçlardan birinin diğerine göre hızının büyüklüğü nedir?', 'v', ['2v', 'v√3', 'v√2'], '|v_A − v_B|² = v² + v² − 2v²cos60° = v²; bağıl hız büyüklüğü v\'dir.'),
  ('Yere göre doğuya 2 m/s² ivmeyle hızlanan bir aracın içindeki gözlemci, yolda duran bir taşı nasıl görür?', 'Batıya doğru 2 m/s² ivmeyle hareket ediyor', ['Hareketsiz duruyor', 'Doğuya doğru 2 m/s² ivmeyle hareket ediyor', 'Batıya doğru sabit hızla gidiyor'], 'Hızlanan çerçevede ölçülen ivme a′ = a − A\'dır; taş için a = 0 olduğundan a′ = −2 m/s², yani batıya doğrudur.'),
  ('Bir cismin ivmesini iki farklı gözlemci ölçüyor ve farklı değerler buluyor. Bu durum için en uygun açıklama hangisidir?', 'Gözlemcilerden en az biri ivmeli bir çerçevededir', ['İki gözlemci de sabit hızla hareket etmektedir', 'Cismin hızı çok küçüktür', 'Gözlemciler farklı uzunluk birimi kullanmaktadır'], 'Birbirine göre sabit hızla hareket eden çerçevelerde ivme aynı ölçülür; farklılık ancak çerçeveler arasında bağıl ivme varsa ortaya çıkar.'),
  ('Akıllı telefonun ivmeölçerinden alınan veriler iki kez integral alınarak konum hesaplanıyor. Ölçümdeki küçük ve sabit bir sapma (hata) konum hesabını zamanla nasıl etkiler?', 'Hata zamanın karesiyle büyür', ['Hata zamanla kendiliğinden sıfırlanır', 'Hata sabit kalır', 'Hata yalnız hızı etkiler, konumu etkilemez'], 'Sabit bir ivme hatası δa, hızda δa·t, konumda ½·δa·t² kadar hata doğurur; bu nedenle yalnız ivmeye dayalı konum hesabı kısa sürede bozulur.'),
  ('Bir cisim yarıçapı r olan bir çemberin yarısını sabit süratle dolaşıyor. Bu hareketteki ortalama süratin ortalama hızın büyüklüğüne oranı kaçtır?', 'π/2', ['π', '2', '1'], 'Alınan yol πr, yer değiştirme 2r\'dir; aynı süreye bölündüğünde oran πr/(2r) = π/2 olur.'),
  ('Konumu zamanla sürekli ve pürüzsüz değişen bir cisim için belli bir zaman aralığında hangisi kesinlikle doğrudur?', 'Anlık hızın ortalama hıza eşit olduğu en az bir an vardır', ['Anlık hız her an ortalama hıza eşittir', 'Anlık hız hiçbir an ortalama hıza eşit olmaz', 'Ortalama hız her zaman sıfırdır'], 'Ortalama değer teoremine göre konum-zaman eğrisinde, kirişe paralel teğetin bulunduğu en az bir nokta vardır.'),
  ('Bir vektörün x ve y eksenleriyle yaptığı açıların her biri 60° ise z ekseniyle yaptığı açı kaç derecedir? (Vektörün z bileşeni pozitif)', '45°', ['60°', '30°', '90°'], 'Doğrultu kosinüsleri için cos²α + cos²β + cos²γ = 1\'dir: 1/4 + 1/4 + cos²γ = 1, cosγ = √2/2, γ = 45°.'),
  ('Aynı noktadan aynı anda, aynı süratle ama farklı yönlere atılan çok sayıda taşın t anındaki konumları için hangisi doğrudur? (Hava direnci yok)', 'Serbestçe düşen bir çemberin üzerindedirler', ['Yatay bir doğru boyunca dizilirler', 'Düşey bir doğru boyunca dizilirler', 'Aynı noktada bulunurlar'], 'Her taşın konumu v₀t uzunluğunda bir vektör artı hepsi için ortak −½gt² düşüşüdür; bu da yarıçapı v₀t olan ve serbestçe düşen bir çemberi tanımlar.'),
  ('Sabit ivmeli bir cisim için hızın karesinin konuma karşı (v²–x) grafiği nasıldır?', 'Eğimi 2a olan bir doğru', ['Eğimi a olan bir parabol', 'Yatay bir doğru', 'Eğimi a/2 olan bir doğru'], 'v² = v₀² + 2a(x − x₀) bağıntısı v² ile x arasında doğrusal bir ilişkidir ve eğim 2a\'dır.'),
  ('Bir çatıdan serbest bırakılan saksı 2 m yüksekliğindeki bir pencerenin önünden 0,2 s\'de geçiyor. Saksı pencerenin üst kenarına göre kaç metre yukarıdan bırakılmıştır? (g = 10 m/s²)', '4,05 m', ['2 m', '5 m', '8,1 m'], 'Pencerenin üstündeki hız v olsun: 2 = 0,2v + 5·0,04, v = 9 m/s. Bu hıza ulaşmak için 9²/20 = 4,05 m düşmek gerekir.'),
  ('Bir otomobilin hız göstergesi tekerleğin dönme sayısından hız hesaplar. Araca fabrika ayarındakinden daha büyük çaplı tekerlek takılırsa gösterge için hangisi doğrudur?', 'Gerçek hızdan daha düşük değer gösterir', ['Gerçek hızdan daha yüksek değer gösterir', 'Gerçek hızı doğru gösterir', 'Hiç değer göstermez'], 'Büyük tekerlek her turda daha çok yol alır; gösterge eski çevreyle hesap yaptığından gerçek hızın altında kalır.'),
  ('Aynı noktadan aynı anda çıkan iki aracın hız-zaman grafikleri arasında kalan alan neyi verir?', 'Araçlar arasındaki uzaklığın değişimini', ['Araçların toplam yolunu', 'Araçların ivme farkını', 'Araçların ortalama hızını'], 'İki grafiğin farkının alanı bağıl yer değiştirmedir; bu da aralarındaki uzaklığın ne kadar değiştiğini gösterir.'),
  ('Doğrusal harekette konum-zaman grafiğinin altında kalan alan için hangisi doğrudur?', 'Kinematikte doğrudan anlamlı bir nicelik vermez', ['Alınan yolu verir', 'Ortalama hızı verir', 'Yer değiştirmeyi verir'], 'Alan yorumu hız-zaman (yer değiştirme) ve ivme-zaman (hız değişimi) grafikleri için geçerlidir; konum çarpı zaman kinematikte kullanılan bir nicelik değildir.'),
];
